import{_ as v,b as l,c as i,d as a,t as c,C as b,u as o}from"./index-I5uTs6b4.js";const n={class:"level-page"},p={class:"level-content"},u={class:"level-title"},h={__name:"Level13",props:{id:{type:String,required:!0}},setup(s){const e=o();function d(){sessionStorage.setItem("skipIntro","1"),e.push("/")}return(r,t)=>(l(),i("div",n,[a("button",{class:"back-btn",onClick:d},"← Back to Index"),a("div",p,[a("h1",u,"SI-"+c(s.id),1),t[0]||(t[0]=b('<p class="level-name" data-v-9b64e24a>&quot;天文钟&quot;</p><section class="faction-section meg" data-v-9b64e24a><div class="faction-tag" data-v-9b64e24a>MEG 侧</div><div class="section" data-v-9b64e24a><h2 data-v-9b64e24a>生存难度：א</h2><div class="difficulty" data-v-9b64e24a><ul class="class-list" data-v-9b64e24a><li data-v-9b64e24a><span class="class-bullet unsafe" data-v-9b64e24a></span> 不安全</li><li data-v-9b64e24a><span class="class-bullet twist" data-v-9b64e24a></span> 时空扭曲</li><li data-v-9b64e24a><span class="class-bullet entity" data-v-9b64e24a></span> 未知实体</li></ul></div></div><div class="section" data-v-9b64e24a><h2 data-v-9b64e24a>层级描述</h2><p data-v-9b64e24a>该层级被描述为一个无限延伸的，内部空间具有精密机械结构的房间。其背景色为日落后天空的蓝紫色，无自然光源，但金属零件会散发光泽。经探索，该层级的房间均为同心扇环状。由于该层级的特殊性质，对其圆心和圆周的探索均以失败告终。</p><p data-v-9b64e24a>流浪者刚进入该层级时，房间内最大的机械零件不超过 1m³；越靠近圆心的房间，其面积越小，内部零件也更加细小；越远离圆心的房间，其面积越大。已探明最小的零件体积约为 1dm³，最大的零件体积约为 1000m³。一位资深机械师发现了明显的星座轮等结构，推测它们大概率是在驱动一台天文钟。</p><p data-v-9b64e24a>该层级随探索距离的增加会发生<strong data-v-9b64e24a>时空扭曲</strong>。向圆心探索的流浪者会发现过去一段时间内的场景；向外探索则会提前体验自己的未来——大多是流浪者最大的愿望、理想、执念。但事件走向会从理想逐渐变得糟糕，带来精神损伤。MEG 不建议流浪者在该层级久留。</p><p data-v-9b64e24a>在探索过程中，流浪者可在层级模拟出的场景中找到一种特殊容器，内装有<strong data-v-9b64e24a>液态星云</strong>。拾取容器后即可切出层级。</p></div><div class="section" data-v-9b64e24a><h2 data-v-9b64e24a>探索记录</h2><p data-v-9b64e24a>SI-13 是非常稳定的能源产出地。MEG 曾建立开采队伍，但在第【数据删除】次任务中只有少数几人成功切出。结论：该层级带来的精神损伤不可逆，正常流浪者一生中只能有限次地探索该层级。</p><p data-v-9b64e24a>MEG 曾招募完全失忆的流浪者向圆心探索，他们均未受到精神损伤——但也未能发现星云。一位自称曾出生于战火之中的流浪者（没有&quot;美好的回忆&quot;）自愿探索，但在进入第【数据删除】个房间时突然精神崩溃。</p></div><div class="section classified" data-v-9b64e24a><h2 data-v-9b64e24a>BAUT 讯息</h2><p data-v-9b64e24a>近日 SI-13 的切入人次异常上升。BAUT 出于人道主义关怀，将在每月配给中添加星云补给。BAUT 在此呼吁流浪者不要在非必要情况下进入 SI-13。</p></div></section><section class="faction-section baut" data-v-9b64e24a><div class="faction-tag baut-tag" data-v-9b64e24a>BAUT 侧 · C 等级以上</div><div class="section" data-v-9b64e24a><h2 data-v-9b64e24a>层级性质：E</h2><div class="difficulty" data-v-9b64e24a><ul class="class-list" data-v-9b64e24a><li data-v-9b64e24a><span class="class-bullet stable" data-v-9b64e24a></span> 稳定</li><li data-v-9b64e24a><span class="class-bullet safe" data-v-9b64e24a></span> 易开发</li><li data-v-9b64e24a><span class="class-bullet energy" data-v-9b64e24a></span> 含能</li></ul></div></div><div class="section" data-v-9b64e24a><h2 data-v-9b64e24a>叙述</h2><p data-v-9b64e24a>这一层是重要的能源基地，外观上看是无限广阔的&quot;星云海&quot;。一般情况下，储能部派遣队员部署采集装置直接在星云中开采，也可经由 SI-？？的观察窗间接开采。MEG 发现 SI-13 的布拉格碎片并公布文档后，切入人次异常升高。为确保能源安全，月度配给物质中添加了星云项目。</p></div><div class="section" data-v-9b64e24a><h2 data-v-9b64e24a>实体：布拉格碎片</h2><p data-v-9b64e24a>该实体外形类似一面简化后的前厅&quot;布拉格广场&quot;上的天文钟，悬浮在无限的星云&quot;海&quot;中，数量无穷多。内部结构由&quot;扇区&quot;和&quot;层&quot;两个维度定义，几何中心处为控制核心。该实体吸收其他智慧实体在心理落差中释放的精神力来维持自身运转，同时将星云吸收、压缩、封装以吸引其他智慧实体。层级中存在&quot;无名之火&quot;用于维持布拉格碎片相对分散的状态。</p></div><div class="section" data-v-9b64e24a><h2 data-v-9b64e24a>特殊事件</h2><p data-v-9b64e24a>维护部上报了一起布拉格碎片异常消失的情况。行动部 EL021 介入，但没有找到目标人物。随后 BAUT 发布广域通讯寻找一名昔民女孩。在等待回信期间，SI-？？观察窗传回的全局影像中出现了一名未知男性。数支行动小队开始在稳定区内寻找相关线索。</p></div></section><div class="section" data-v-9b64e24a><h2 data-v-9b64e24a>入口与出口</h2><h3 class="sub-heading" data-v-9b64e24a>入口</h3><p data-v-9b64e24a>在任意层级找到指针位置异常的时钟并切出可到达此层级。MEG 不建议流浪者在 SI 层群佩戴非传统形制手表。在 Level SI-3 中切入显示着天文钟的电子屏幕可进入此层级。</p><h3 class="sub-heading" data-v-9b64e24a>出口</h3><p data-v-9b64e24a>拾取星云后切出可来到 Level SI-6。推测探索到圆心或圆周可到达 SI-1（未经证实）。诺克立普贴使用后有 82% 的概率失效。</p></div>',4))])]))}},f=v(h,[["__scopeId","data-v-9b64e24a"]]);export{f as default};
